using System;
using System.Text.RegularExpressions;
using System.Xml;
using System.Xml.Linq;
using MediaBrowser.Model.Logging;

namespace Emby.Okuzukey.Helpers
{
    /// <summary>
    /// Shared, tolerant XML parsing used by all local XML-based metadata sources
    /// (NFO, ComicInfo.xml, ...).
    /// </summary>
    /// <remarks>
    /// Real-world files of this kind are frequently generated by other tools (or by hand)
    /// without proper XML escaping. The single, very common and safe-to-fix case is a bare
    /// <c>&amp;</c> in free text (e.g. a publisher name like "Secker &amp; Warburg"), which makes
    /// the file invalid XML and would otherwise cause the whole file to be skipped. Other kinds of
    /// malformed XML (e.g. unescaped <c>&lt;</c>/<c>&gt;</c>) are deliberately never auto-corrected,
    /// since guessing a fix there is unsafe and could silently produce wrong data instead of just
    /// skipping the file.
    /// </remarks>
    internal static class XmlSanitizer
    {
        /// <summary>
        /// Matches a bare <c>&amp;</c> that is not already part of a valid XML entity or
        /// character reference (<c>&amp;amp;</c>, <c>&amp;lt;</c>, <c>&amp;gt;</c>, <c>&amp;apos;</c>,
        /// <c>&amp;quot;</c>, <c>&amp;#123;</c>, <c>&amp;#x7B;</c>).
        /// </summary>
        private static readonly Regex UnescapedAmpersandRegex = new Regex(
            "&(?!(?:amp|lt|gt|apos|quot);|#[0-9]+;|#x[0-9A-Fa-f]+;)",
            RegexOptions.Compiled);

        /// <summary>
        /// Parses <paramref name="xmlText"/> as an <see cref="XDocument"/>. If the well-formed
        /// parse fails with an <see cref="XmlException"/>, a single fallback attempt is made:
        /// bare <c>&amp;</c> characters are escaped to <c>&amp;amp;</c> and the result is parsed
        /// again, logging a <see cref="ILogger.Warn"/> message so the correction stays visible.
        /// If the sanitized text is identical to the original (no unescaped <c>&amp;</c> was
        /// found) or the retry still fails, the original <see cref="XmlException"/> is rethrown
        /// unchanged.
        /// </summary>
        /// <param name="xmlText">The raw, already-decoded XML text to parse.</param>
        /// <param name="sourceDescription">Human-readable description of the source (e.g. a file
        /// path) used only for the log message.</param>
        /// <param name="logger">Logger used for the auto-correction warning.</param>
        public static XDocument ParseWithAmpersandFallback(string xmlText, string sourceDescription, ILogger logger)
        {
            try
            {
                return SafeXml.Parse(xmlText);
            }
            catch (XmlException)
            {
                var sanitizedText = UnescapedAmpersandRegex.Replace(xmlText, "&amp;");

                if (string.Equals(sanitizedText, xmlText, StringComparison.Ordinal))
                {
                    throw;
                }

                var document = SafeXml.Parse(sanitizedText);

                logger.Warn(
                    "[Okuzukey] '{0}' contained unescaped '&' characters; auto-corrected them to '&amp;' before parsing.",
                    sourceDescription);
                return document;
            }
        }
    }
}
